from collect import *
def main():
 pools=read('v4-state.json');sel=next(p for p in pools if p['poolId']==SELECTED);price=Fraction(sel['slot0']['sqrtPriceX96']**2,1<<192)
 rows=[]
 for p in pools:
  physical=Fraction(p['slot0']['sqrtPriceX96']**2,1<<192);low=max(price,physical)*10000/10500;high=min(price,physical)*10000/9500;overlap=low<=high
  rows.append({'poolId':p['poolId'],'key':p['key'],'L':p['liquidity'],'principal_fee_compatible':p['principal_compatible_fee'],'pool_ZZZperETH_price_ratio_to_selected':str(physical/price),'ratio_float':float(physical/price),'shared_reference_500bps_bands_overlap':overlap,'possible_reference_price_lower_exact':str(low),'possible_reference_price_upper_exact':str(high),'scope':'Principal target+execution venue only, not converter. Necessary pre-swap condition, not source qualification or full-operation acceptance. Hardcoded max500bps is an engineering ceiling, not a chosen setting. Exact on-chain root quantization is sub-1e-12bps here and cannot rescue the large nonoverlapping gaps.'})
 put('common-reference-bands.json',{'derivation':'_validSpot bounds price/reference in[0.95,1.05]; any shared reference must lie within[price/1.05,price/0.95] for both target and venue. Intersection exists iff max(priceA,priceB)/min(priceA,priceB)<=1.05/0.95. Uses native PoolKey order (ZZZ raw units per native ETH rawunit).','rows':rows})
 lines=['\nA further principal-only admission check does not need a chosen USD truth: target and balancing venue must share one ETH/fixedZZZ reference, and each has a hard500bps spot ceiling. Their reference bands overlap only when `max(P)/min(P) <= 1.05/0.95` (about1.105263). Here P is ZZZ-per-ETH from physical sqrt. Alternative10018 is about'+f"{next(r['ratio_float']for r in rows if r['poolId'].startswith('0x9fa185')):.6f}"+'times selected P, so it cannot be admitted simultaneously with selected under any shared reference within that ceiling. Of the eight active principal-fee-compatible states, only selected itself and thin07ee2b have overlapping pre-swap bands. This is necessary admission geometry, not qualified price truth, a recommended500bps setting or a proof every possible contribution fails. It does not apply to the separate earned converter, which retains its own independent-price/output guards. `common-reference-bands.json` records all95 states.\n']
 with(ROOT/'ROUTES_WITH_BANDS.md').open('x',encoding='utf-8',newline='\n')as f:f.write((ROOT/'ROUTES_FINAL.md').read_text()+''.join(lines))
 put('final-manifest-with-bands.json',[{'path':p.name,'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}for p in sorted(ROOT.iterdir())if p.is_file()and p.name!='final-manifest-with-bands.json'])
 for row in read('final-manifest-with-bands.json'):assert hashlib.sha256((ROOT/row['path']).read_bytes()).hexdigest()==row['sha256']
 print(json.dumps({'active_principal_overlap':[r['poolId']for r in rows if r['L']and r['principal_fee_compatible']and r['shared_reference_500bps_bands_overlap']],'payloads':len(read('final-manifest-with-bands.json'))}))
if __name__=='__main__':main()
